\begin{lemma}[Step 4b: figure arm at $45^\circ$]
\label{lem:IPhO2026Problems_problem_IPhO_2026_1_A_1:pressure_figure_arm_eq}
\lean{IPhO2026_1_A_1.pressure_figure_arm_eq}
\uses{def:IPhO2026Problems_problem_IPhO_2026_1_A_1:pressureFigureArm}
